changeSet.sql:
CREATE TABLE calendar_event_series ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, deleted BOOLEAN NOT NULL DEFAULT FALSE, insert_by VARCHAR(255), insert_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, edit_by VARCHAR(255), edit_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, entity_version BIGINT NOT NULL DEFAULT 0, name VARCHAR(255) NOT NULL, description TEXT, state VARCHAR(32), location VARCHAR(1000), fee NUMERIC(19,4), reminder_minutes INTEGER, time_zone VARCHAR(64) NOT NULL, first_start_local TIMESTAMP WITHOUT TIME ZONE NOT NULL, duration_minutes INTEGER NOT NULL CHECK (duration_minutes > 0), frequency VARCHAR(16) NOT NULL CHECK (frequency IN ('DAILY', 'WEEKLY', 'MONTHLY', 'YEARLY')), interval_value INTEGER NOT NULL CHECK (interval_value > 0), week_days VARCHAR(32), end_type VARCHAR(16) NOT NULL CHECK (end_type IN ('COUNT', 'UNTIL')), occurrence_count INTEGER, until_local_date DATE, CONSTRAINT ck_calendar_event_series_end CHECK ( (end_type = 'COUNT' AND occurrence_count IS NOT NULL AND occurrence_count > 0 AND until_local_date IS NULL) OR (end_type = 'UNTIL' AND occurrence_count IS NULL AND until_local_date IS NOT NULL) ) );
CREATE TABLE calendar_event_series_cost ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, series_id BIGINT NOT NULL REFERENCES calendar_event_series(id) ON DELETE CASCADE, description TEXT NOT NULL, amount NUMERIC(19,4), display_order INTEGER NOT NULL, deleted BOOLEAN NOT NULL DEFAULT FALSE, insert_by VARCHAR(255) NOT NULL DEFAULT 'system', insert_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, edit_by VARCHAR(255) NOT NULL DEFAULT 'system', edit_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP );
ALTER TABLE calendar_event ADD COLUMN series_id BIGINT REFERENCES calendar_event_series(id) ON DELETE RESTRICT, ADD COLUMN original_start_date TIMESTAMPTZ, ADD COLUMN series_sequence INTEGER, ADD COLUMN series_exception BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN series_excluded BOOLEAN NOT NULL DEFAULT FALSE, ADD CONSTRAINT ck_calendar_event_series_fields CHECK ( (series_id IS NULL AND original_start_date IS NULL AND series_sequence IS NULL AND series_exception = FALSE AND series_excluded = FALSE) OR (series_id IS NOT NULL AND original_start_date IS NOT NULL AND series_sequence IS NOT NULL AND series_sequence > 0) );
CREATE UNIQUE INDEX uq_calendar_event_series_original_start ON calendar_event(series_id, original_start_date) WHERE series_id IS NOT NULL; CREATE INDEX idx_calendar_event_series_sequence ON calendar_event(series_id, series_sequence) WHERE series_id IS NOT NULL; CREATE INDEX idx_calendar_event_series_future ON calendar_event(series_id, deleted, start_date); CREATE INDEX idx_calendar_event_series_active ON calendar_event_series(deleted, first_start_local);
WITH ranked AS ( SELECT id, ROW_NUMBER() OVER (PARTITION BY event_id, user_id ORDER BY id DESC) AS position FROM push_reminders WHERE deleted = FALSE AND sent = FALSE ) UPDATE push_reminders reminder SET deleted = TRUE, edit_by = 'recurrence-migration', edit_date = CURRENT_TIMESTAMP FROM ranked WHERE reminder.id = ranked.id AND ranked.position > 1;
CREATE UNIQUE INDEX uq_push_reminder_pending_event_user ON push_reminders(event_id, user_id) WHERE deleted = FALSE AND sent = FALSE;
